def _healthcheck_budget_s(svc: dict[str, Any]) -> float:
    hc = svc.get("healthcheck")
    if not hc or not isinstance(hc, dict):
        return _duration_seconds(0) + _duration_seconds("5s") * 3
    start = _duration_seconds(hc.get("start_period", 0))
    interval = _duration_seconds(hc.get("interval", "5s"))
    if interval <= 0:
        interval = 5.0
    retries = int(hc.get("retries", 3))
    return start + interval * retries


def _readiness_budget_s(plan: dict[str, Any], app_service: str) -> float:
    services = plan.get("services") or {}
    if not isinstance(services, dict):
        return _READINESS_MIN_S
    app_spec = services.get(app_service)
    if not isinstance(app_spec, dict):
        app_spec = {}
    names = {app_service, *_depends_on_service_names(app_spec)}
    budgets = []
    for name in names:
        spec = services.get(name)
        if isinstance(spec, dict):
            budgets.append(_healthcheck_budget_s(spec))
        else:
            budgets.append(_healthcheck_budget_s({}))
    base = max(budgets) if budgets else _healthcheck_budget_s({})
    total = base + _READINESS_SLACK_S
    return min(_READINESS_CAP_S, max(_READINESS_MIN_S, total))


def _wait_http(
    network: str,
    url: str,
    budget_s: float,
    poll_s: float = _HEALTH_POLL_S,
    progress: BootProgress | None = None,
) -> bool:
    start = time.monotonic()
    deadline = start + budget_s
    if progress is not None:
        progress.boot_note(f"boot: waiting for {url} (budget {int(budget_s)}s)")
    while time.monotonic() < deadline:
        if _probe_http(network, url):
            return True
        if progress is not None:
            progress.health_tick(time.monotonic() - start, budget_s)
        time.sleep(poll_s)
    return False

