"""Ladder and bracket state (tech_doc.md §9.4)."""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Literal

from loadline.constants import BRACKET_TARGET, LADDER_FACTOR, LADDER_START
from loadline.core.measurement_window import is_measurement_gap_verdict, verdict_base
from loadline.core.verdict import VerdictCode, moves_bracket

BracketStatus = Literal[
    "bracketed",
    "below_ladder",
    "above_ladder",
    "application_limited",
    "generator_limited",
    "above_measured_range",
    "measurement_incomplete",
    "invalid",
]


@dataclass
class LadderState:
    rate_rps: float = float(LADDER_START)
    lo: float | None = None
    hi: float | None = None
    above_ladder: bool = False
    generator_limited: bool = False
    invalid_code: str | None = None
    below_ladder: bool = False
    measurement_incomplete: bool = False
    above_measured_range: bool = False
    last_valid_pass_rps: float | None = None
    last_achieved_rps: float | None = None

    def next_rate(self) -> float:
        return self.rate_rps * LADDER_FACTOR

    def record(self, rate: float, verdict: VerdictCode) -> None:
        if verdict == "generator_limited":
            self.generator_limited = True
            return
        if not moves_bracket(verdict):
            self.invalid_code = verdict
            return
        if verdict == "pass":
            self.lo = rate
            self.last_valid_pass_rps = rate
        else:
            if self.lo is None:
                self.below_ladder = True
            self.hi = rate
        self.rate_rps = self.next_rate()

    def note_achieved(self, achieved_rps: float | None) -> None:
        if achieved_rps is not None:
            self.last_achieved_rps = achieved_rps

    def status(self) -> BracketStatus:
        return self.terminal_status()

    def terminal_status(self) -> BracketStatus:
        if self.measurement_incomplete:
            return "measurement_incomplete"
        if self.invalid_code and is_measurement_gap_verdict(self.invalid_code):
            return "measurement_incomplete"
        if self.generator_limited:
            if self.lo is not None and self.hi is None:
                return "generator_limited"
            return "generator_limited"
        if self.above_measured_range:
            return "above_measured_range"
        if self.lo is not None and self.hi is not None:
            return "bracketed"
        if self.hi is not None and self.lo is not None:
            return "bracketed"
        if self.hi is not None and verdict_base(self.invalid_code or "") == "fail":
            return "application_limited"
        if self.hi is not None:
            return "application_limited"
        if self.below_ladder:
            return "below_ladder"
        if self.lo is not None and self.hi is None:
            return "above_ladder"
        if self.invalid_code:
            return "invalid"
        return "below_ladder"

    def capacity_rps(self) -> float | None:
        """Highest offered rate with a valid pass verdict (not achieved throughput under generator stress)."""
        return self.last_valid_pass_rps if self.last_valid_pass_rps is not None else self.lo

    def refine_rate(self) -> float | None:
        if self.lo is None or self.hi is None:
            return None
        return (self.lo * self.hi) ** 0.5

    def needs_refine(self, refinements: int) -> bool:
        if self.lo is None or self.hi is None or self.lo <= 0:
            return False
        return (self.hi / self.lo) > BRACKET_TARGET


def vu_count(rate_rps: float, baseline_p95_s: float) -> int:
    nominal = math.ceil(rate_rps * baseline_p95_s * 1.5) + 2
    return max(nominal, 1)


def vu_cap(rate_rps: float, baseline_p95_s: float) -> int:
    return 4 * vu_count(rate_rps, baseline_p95_s)

