def investigator_should_run(ladder_state: LadderState, run_dir: Path) -> tuple[bool, str]:
    status = ladder_state.terminal_status()
    if status == "measurement_incomplete":
        return False, "ladder ended measurement_incomplete; no valid steps to investigate"
    bracket = load_ladder_state_from_bracket(run_dir)
    if bracket.get("measurement_incomplete"):
        return False, "bracket measurement_incomplete"

    if ladder_state.lo is not None or ladder_state.hi is not None:
        return True, "valid bracket step recorded"
    if ladder_state.generator_limited:
        if _wave_has_telemetry(run_dir, "baseline"):
            return True, "generator_limited with telemetry"
    if _any_valid_ledger_step(run_dir):
        return True, "ledger contains pass/fail or generator_limited step"
    return False, "no valid pass/fail or limit-attributed step"


def _wave_has_telemetry(run_dir: Path, wave: str) -> bool:
    return (run_dir / "waves" / wave / "telemetry.json").is_file()


def _any_valid_ledger_step(run_dir: Path) -> bool:
    path = run_dir / "ledger.jsonl"
    if not path.is_file():
        return False
    for line in path.read_text().splitlines():
        if not line.strip():
            continue
        try:
            ev = json.loads(line)
        except json.JSONDecodeError:
            continue
        if ev.get("kind") != "experiment_finished":
            continue
        v = str(ev.get("verdict") or "")
        if moves_bracket(v):  # type: ignore[arg-type]
            return True
        if verdict_base(v) == "generator_limited":
            return True
        if is_measurement_gap_verdict(v):
            continue
    return False

