  let pick = Math.random() * total;
  let chosen = OPS[0];
  for (const op of OPS) {{
    pick -= op.weight;
    if (pick <= 0) {{ chosen = op; break; }}
  }}
  const params = {{ headers: chosen.headers || {{}}, tags: {{ operation: chosen.id }} }};
