"""run_k6 investigator tool — execute plan and return agent-facing metrics."""

from __future__ import annotations

import re
from typing import Any
from urllib.parse import urlparse

from loadline.adapters.generator.k6_compiler import CompileError, compile_plan
from loadline.adapters.generator.k6_runner import run_k6_plan
from loadline.adapters.generator.k6_summary import parse_handle_summary
from loadline.investigator.deps import InvestigationDeps


def _app_target(boot: dict[str, Any]) -> tuple[str, int]:
    health = boot.get("health") or {}
    url = health.get("url") or ""
    if url:
        parsed = urlparse(url)
        host = parsed.hostname or "app"
        port = parsed.port or 8000
        return host, port
    services = boot.get("services") or []
    if services:
        name = services[0].get("name") or "app"
        port = int(services[0].get("port") or 8000)
        return name, port
    return "app", 8000


def _slug(path: str, method: str) -> str:
    clean = re.sub(r"[^a-zA-Z0-9]+", "_", path.strip("/")) or "root"
    return f"{method.lower()}_{clean}"[:64]


def build_plan_from_endpoints(
    endpoints: list[dict[str, Any]],
    *,
    rate: float,
    duration_s: int,
    boot: dict[str, Any],
) -> dict[str, Any]:
    service, port = _app_target(boot)
    mix: list[dict[str, Any]] = []
    n = len(endpoints)
    weight = max(1, 100 // n) if n else 100
    for ep in endpoints:
        path = str(ep.get("path") or "/")
        if not path.startswith("/"):
            path = f"/{path}"
        op_id = str(ep.get("id") or _slug(path, str(ep.get("method") or "GET")))
        op: dict[str, Any] = {
            "id": op_id,
            "service": service,
            "port": port,
            "selector": {"method": str(ep.get("method") or "GET").upper(), "path": path},
        }
        if ep.get("body") is not None:
            op["body"] = ep["body"]
        if ep.get("headers"):
            op["headers"] = ep["headers"]
        mix.append({"weight": weight, "op": op})
    return {"mix": mix, "shape": {"rate": int(rate), "duration": int(duration_s)}}


def format_run_k6_result(summary_raw: dict[str, Any], *, offered_rps: float, duration_s: int) -> dict[str, Any]:
    vu_ceiling = int(summary_raw.get("vu_ceiling") or 50)
    vus_max = summary_raw.get("vus_max")
    vus_max_reached = bool(summary_raw.get("vus_max_reached"))
    dropped = int(summary_raw.get("dropped_iterations") or 0)
    operations_out: dict[str, Any] = {}
    for op_id, row in (summary_raw.get("operations") or {}).items():
        if not isinstance(row, dict):
            continue
        count = int(row.get("count") or row.get("http_reqs") or 0)
        achieved = float(row.get("achieved_rps") or (count / duration_s if duration_s else 0))
        operations_out[str(op_id)] = {
            "count": count,
            "error_rate": float(row.get("error_rate") or row.get("http_req_failed") or 0),
            "p50_ms": row.get("p50_ms"),
            "p95_ms": row.get("p95_ms"),
            "achieved_rps": achieved,
            "status_counts": dict(row.get("status_counts") or {}),
        }
    return {
        "offered_rps": float(offered_rps),
        "duration_s": int(duration_s),
        "dropped_iterations": dropped,
        "vus_max": vus_max,
        "vu_ceiling": vu_ceiling,
        "vus_max_reached": vus_max_reached,
        "operations": operations_out,
    }


def run_k6(
    deps: InvestigationDeps,
    endpoints: list[dict[str, Any]],
    rate: float,
    duration_s: int,
) -> dict[str, Any]:
    if not endpoints:
        return {"error": "endpoints must not be empty"}
    if rate <= 0 or duration_s <= 0:
        return {"error": "rate and duration_s must be positive"}
    allowed = deps.allowed_hosts
    network = deps.network
    if not allowed or not network:
        return {"error": "sandbox network not configured"}
    plan = build_plan_from_endpoints(endpoints, rate=rate, duration_s=duration_s, boot=deps.boot)
    compiled = compile_plan(plan, allowed)
    if isinstance(compiled, CompileError):
        return {"error": compiled.message}
    deps.k6_wave_index += 1
    wave = f"agent-k6-{deps.k6_wave_index}"
    result = run_k6_plan(
        plan=plan,
        allowed_hosts=allowed,
        network=network,
        run_id=deps.run_id,
        run_dir=deps.run_dir,
        wave_name=wave,
    )
    if not result.summary.parse_ok:
        excerpt = (result.stderr or result.summary.error or "k6 failed")[:2000]
        return {"error": excerpt}
    raw = result.summary.raw_json or {}
    out = format_run_k6_result(raw, offered_rps=rate, duration_s=duration_s)
    deps.ledger.append(
        "k6_run",
        evidence_ids=[f"ev-k6-{deps.k6_wave_index}"],
        wave=wave,
        plan=plan,
        result=out,
    )
    return out

"""Investigator tools: repo, read_file, run_k6."""

from __future__ import annotations

import re
import subprocess
from typing import Any, Literal

from pydantic import BaseModel, Field
from pydantic_ai import RunContext

from loadline.investigator.deps import InvestigationDeps, ReadRange
from loadline.investigator.k6_tool import run_k6 as execute_run_k6

FORBIDDEN_READ = re.compile(r"(\.env|\.pem|credentials|id_rsa)", re.I)


class EndpointSpec(BaseModel):
    id: str | None = None
    method: str = "GET"
    path: str
    body: dict[str, Any] | None = None
    headers: dict[str, str] | None = None


class RunK6Input(BaseModel):
    endpoints: list[EndpointSpec] = Field(min_length=1)
    rate: float = Field(gt=0)
    duration_s: int = Field(gt=0, le=600)


def _deny_path(path: str) -> bool:
    return bool(FORBIDDEN_READ.search(path))


def repo(
    ctx: RunContext[InvestigationDeps],
    action: Literal["search", "def", "neighbors", "impact"],
    query: str = "",
    symbol: str = "",
) -> dict[str, Any]:
    if action == "search":
        if not query.strip():
            return {"error": "query is required for action=search"}
        return search_code(ctx, query)
    if not symbol.strip():
        return {"error": "symbol is required for graph actions"}
    return code_graph(ctx, action, symbol)


def search_code(ctx: RunContext[InvestigationDeps], query: str) -> dict[str, Any]:
    deps = ctx.deps
    hits: list[dict[str, Any]] = []
    coverage = "entire"
    if deps.graph is not None:
        try:
            cmd = deps.graph.ranked_command()
            args = [
                cmd,
                "--repo",
                str(deps.repo_root),
                "--query",
                query,
                "--format",
                "json",
                "--top-k",
                "8",
                "--profile",
                "full",
            ]
            out = deps.graph.run(args)
            if out.ok:
                hits.append({"source": "entire_graph", "command": cmd, "text": out.text[:6000]})
            else:
                coverage = "degraded"
        except Exception as exc:
            coverage = "degraded"
            hits.append({"source": "entire_graph", "error": str(exc)})
    try:
        proc = subprocess.run(
            ["rg", "-n", "--max-count", "20", query, str(deps.repo_root)],
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
        )
    except FileNotFoundError:
        proc = None
    if proc and proc.stdout:
        hits.append({"source": "ripgrep", "text": proc.stdout[:4000]})
    if not hits:
        return {"hits": [], "coverage": coverage, "note": "empty result; try another query"}
    return {"hits": hits, "coverage": coverage}


def code_graph(
    ctx: RunContext[InvestigationDeps],
    mode: Literal["def", "neighbors", "impact"],
    symbol: str,
) -> dict[str, Any]:
    deps = ctx.deps
    if deps.graph is None:
        return {"error": "code graph unavailable", "degraded": True}
    if mode == "neighbors":
        args = ["neighbors", "--repo", str(deps.repo_root), "--symbol", symbol]
    elif mode == "impact":
        args = ["impact", "--repo", str(deps.repo_root), "--symbol", symbol]
    else:
        args = ["def", "--repo", str(deps.repo_root), "--symbol", symbol]
    if deps.dirty_worktree and deps.graph.edges_supports_worktree():
        args.append("--worktree")
    out = deps.graph.run(args)
    return {
        "mode": mode,
        "symbol": symbol,
        "text": out.text[:6000],
        "ok": out.ok,
    }


def read_file(
    ctx: RunContext[InvestigationDeps],
    path: str,
    start_line: int,
    end_line: int,
) -> dict[str, Any]:
    deps = ctx.deps
    if end_line - start_line > 200:
        return {"error": "range too large; use at most 200 lines per call"}
    target = (deps.repo_root / path).resolve()
    if not str(target).startswith(str(deps.repo_root.resolve())):
        return {"error": "path outside repository"}
    if _deny_path(path):
        return {"error": "path denied by policy"}
    if not target.is_file():
        return {"error": "file not found"}
    lines = target.read_text(encoding="utf-8", errors="ignore").splitlines()
    start = max(1, start_line)
    end = min(len(lines), end_line)
    snippet = "\n".join(f"{i + 1}:{lines[i]}" for i in range(start - 1, end))
    deps.read_ranges.append(ReadRange(path=path, start_line=start, end_line=end))
    evidence_id = f"ev-read-{len(deps.read_ranges)}"
    return {"path": path, "start_line": start, "end_line": end, "snippet": snippet[:6000], "evidence_id": evidence_id}


def run_k6_tool(ctx: RunContext[InvestigationDeps], payload: RunK6Input) -> dict[str, Any]:
    endpoints = [ep.model_dump(exclude_none=True) for ep in payload.endpoints]
    return execute_run_k6(ctx.deps, endpoints, payload.rate, payload.duration_s)

"""Build Pydantic AI Investigator agent (repo, read_file, run_k6)."""

from __future__ import annotations

import logging
from typing import Any

from pydantic_ai import Agent, RunContext
from pydantic_ai.usage import UsageLimits

from loadline.investigator.deps import InvestigationDeps
from loadline.investigator.neatlogs_attrs import annotate_tool_span
from loadline.investigator.tools import RunK6Input, read_file, repo, run_k6_tool

logger = logging.getLogger(__name__)


def build_investigator_agent(model: Any, system_prompt: str) -> Agent[InvestigationDeps, str]:
    agent: Agent[InvestigationDeps, str] = Agent(
        model,
        system_prompt=system_prompt,
        output_type=str,
        deps_type=InvestigationDeps,
    )

    @agent.tool(name="repo")
    def repo_tool(
        ctx: RunContext[InvestigationDeps],
        action: str,
        query: str = "",
        symbol: str = "",
    ) -> dict:
        if action not in ("search", "def", "neighbors", "impact"):
            return {"error": "action must be search, def, neighbors, or impact"}
        out = repo(ctx, action, query=query, symbol=symbol)
        return annotate_tool_span(out, adapter="entire")

    @agent.tool(name="read_file")
    def read_file_tool(ctx: RunContext[InvestigationDeps], path: str, start_line: int, end_line: int) -> dict:
        return annotate_tool_span(read_file(ctx, path, start_line, end_line))

    @agent.tool(name="run_k6")
    def run_k6_agent_tool(ctx: RunContext[InvestigationDeps], payload: RunK6Input) -> dict:
        return annotate_tool_span(run_k6_tool(ctx, payload), adapter="k6")

    return agent


def wrap_agent(
    agent: Agent[InvestigationDeps, str],
    *,
    run_id: str | None = None,
    fast: bool = False,
) -> Agent[InvestigationDeps, str]:
    try:
        import neatlogs

        from loadline.neatlogs_setup import LOADLINE_WORKFLOW, init_neatlogs, neatlogs_initialized
        from loadline.settings import get_settings

        settings = get_settings()
        if settings.neatlogs_api_key:
            if not neatlogs_initialized():
                init_neatlogs(
                    settings,
                    workflow_name=LOADLINE_WORKFLOW,
                    run_id=run_id,
                    fast=fast,
                    require_api_key=False,
                )
            return neatlogs.wrap(agent)
    except Exception as exc:
        logger.warning("neatlogs wrap skipped: %s", type(exc).__name__)
    return agent


def default_usage_limits() -> UsageLimits:
    return UsageLimits(request_limit=None, total_tokens_limit=None)

